def _ar_gallery():
    """Write a simple artifacts.html from data/artifacts.json and link it from Collections and Subjects."""
    import json as _j
    items = _j.load(open("data/artifacts.json", encoding="utf-8"))
    # One card per id, listing every profile that carries it.
    groups = []
    seen = {}
    for it in items:
        i = seen.get(it["id"])
        if i is None:
            seen[it["id"]] = len(groups)
            groups.append(dict(it, profiles=[it["profile"]]))
        else:
            if it["profile"] not in groups[i]["profiles"]:
                groups[i]["profiles"].append(it["profile"])
    cards = []
    people = {p["slug"]: p for p in PROFILES}
    for g in groups:
        links = []
        for sl in g["profiles"]:
            nm = people.get(sl, {}).get("name", sl)
            links.append(PL(sl, nm))
        who = " &middot; ".join(links)
        cap = g["title"] + ". " + who + "."
        if g.get("image"):
            # Register once; FIG will render the caption we already stored unless we build by hand.
            if g["image"] not in IMAGES:
                _up_img(g["image"], g["title"], g["text"], g["who"], g.get("lic") or "", g["url"], g["label"])
            # Use a compact gallery figure with profile links in the caption.
            t, _, who_c, lic, src, *lab = IMAGES[g["image"]]
            lab = lab[0] if lab else g["label"]
            fig = (f'<figure class="hfig hfig-flow"><a href="{{P}}assets/images/{g["image"]}">'
                   f'<img src="{{P}}assets/images/{g["image"]}" alt="{t}" loading="lazy"></a>'
                   f'<figcaption><strong>{g["title"]}.</strong> {who} '
                   f'<span class="credit">Image: {who_c}. {lic}. <a href="{src}">Source: {lab}</a></span></figcaption></figure>')
            cards.append(fig)
        else:
            cards.append(
                f'<div class="artifact-text"><p><strong>{g["title"]}.</strong> {who} '
                f'No photograph of the document was obtained for this page. '
                f'<span class="credit">Source: <a href="{g["url"]}">{g["label"]}</a> ({g["who"]}).</span></p></div>'
            )
    body = (
        "<p>Letters, deeds, billheads and other single documents that have come to light as auction or dealer lots, "
        "each credited to the seller or auction house and linked to the person&rsquo;s page. "
        "Photographs remain the property of the houses that made them; they are shown here with credit, for research. "
        "Identifications that have not been confirmed are flagged on the profiles.</p>"
        + "".join(cards)
    )
    page("artifacts.html", "Artifacts at Auction | Tufts Lineage &amp; Legacy", "Collections",
         "Papers and Documents at Auction", "Single lots, with a credit and a link to the profile", body)

    global EXTRA
    _prev = EXTRA
    def EXTRA(path, _prev=_prev):
        out = _prev(path)
        if path == "collections.html" and 'href="{P}artifacts.html"' not in out and 'href="artifacts.html"' not in out:
            _sec = ('{DIV}<section id="papers-at-auction"><h2>Papers and Documents at Auction</h2>'
                    "<p>Letters, deeds, billheads and other single documents that have appeared as auction or dealer lots "
                    "are gathered on the <a href=\"{P}artifacts.html\">Artifacts</a> page, each with a photograph where one could be had, "
                    "a credit to the seller or auction house, and a link to the person&rsquo;s profile.</p></section>")
            if '<section id="artifacts">' in out:
                out = out.replace('<section id="artifacts">', _sec + "{DIV}" + '<section id="artifacts">', 1)
            else:
                out += _sec
        if path == "subjects.html" and "artifacts.html" not in out:
            _li = '<li><a href="artifacts.html">Papers and Documents at Auction</a></li>'
            if '<section id="artifacts"><h2>Artifacts &amp; Collections</h2><ul class="subj-list">' in out:
                out = out.replace(
                    '<section id="artifacts"><h2>Artifacts &amp; Collections</h2><ul class="subj-list">',
                    '<section id="artifacts"><h2>Artifacts &amp; Collections</h2><ul class="subj-list">' + _li,
                    1,
                )
        return out

